CREATE TABLE IF NOT EXISTS functional_knowledge_facts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), fact_code VARCHAR(64) NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, claim TEXT NOT NULL, source_url TEXT, status VARCHAR(32) NOT NULL DEFAULT 'approved', related_codes JSONB NOT NULL DEFAULT '[]'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT chk_functional_fact_status CHECK(status IN('approved','draft','superseded')), CONSTRAINT chk_functional_fact_related CHECK(jsonb_typeof(related_codes)='array'));
